CREATE TABLE IF NOT EXISTS economic_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES economic_entities(id) ON DELETE CASCADE, claim_type text NOT NULL, claim_text text NOT NULL, value_numeric numeric(20,4), value_currency text, status text NOT NULL DEFAULT 'reported', confidence numeric(6,2), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());